"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["30053"],{99206(e){e.exports=JSON.parse('{"id":"FIN-1125","slug":"average-selling-price","term":"Average Selling Price (ASP)","also_known_as":["ASP"],"difficulty":"Advanced","definition":"Average selling price (ASP) is the average price at which a product or group of products is sold over a period, calculated as total revenue from those products divided by the number of units sold.","explanation":["ASP shows what customers are actually paying, which can differ from list prices because of discounts, promotions and changes in the mix of products sold.","For example, if a company sells 25,000 smartphones for total revenue of 5,000,000, its ASP is 200.","Changes in ASP can reflect several factors. Prices may have risen or fallen. Customers may have shifted towards more expensive or cheaper models. Discounting may have increased. Analysts often split revenue growth into changes in volume and changes in ASP to understand what drove sales.","ASP is widely tracked in technology, consumer electronics, cars, property and semiconductors. A falling ASP is not always bad, since a company may cut prices to gain market share or enter new markets, but it can pressure margins. A rising ASP with steady volumes usually signals pricing power or a shift towards premium products."],"note":"","total":1500,"prev":{"slug":"average-revenue-per-user","term":"Average Revenue per User (ARPU)"},"next":{"slug":"backlog","term":"Backlog"}}')}}]);